function Stat({l,v}){return <div className="stat"><small>{l}</small><b>{v}</b><i>实时数据</i></div>}
function CreateTicketModal({onClose,onSaved}){const [roles,setRoles]=useState([]);const [people,setPeople]=useState([]);const [form,setForm]=useState({title:'',description:'',roleId:'',priority:'NORMAL',approverId:''});const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [hint,setHint]=useState('');const [approverName,setApproverName]=useState('');useEffect(()=>{api('/roles').then(setRoles).catch(e=>setError(e.message));api('/people').then(setPeople).catch(()=>{});api('/me/ticket-defaults').then(defaults=>{setForm(f=>({...f,roleId:defaults.roleId?String(defaults.roleId):f.roleId,approverId:defaults.approverId?String(defaults.approverId):f.approverId}));if(defaults.approverName)setApproverName(defaults.approverName+(defaults.approverDepartment?' · '+defaults.approverDepartment:''));else setApproverName('未找到直接领导');if(defaults.roleName)setHint('审批人已自动设为你的直接领导，不能手动修改');}).catch(()=>{});},[]);const submit=async()=>{if(!form.title||!form.description||!form.roleId){setError('请填写标题、问题描述并选择业务组');return}setSaving(true);try{await api('/tickets',{method:'POST',body:JSON.stringify({...form,roleId:Number(form.roleId),approverId:form.approverId?Number(form.approverId):undefined})});onSaved()}catch(e){setError(e.message||'创建工单失败')}finally{setSaving(false)}};return <div className="modal-mask" onClick={onClose}><div className="modal-card ticket-create-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><h2>新建工单</h2><p>{hint||'审批人自动取你的直接领导，不能手动修改。'}</p></div><button className="modal-close" onClick={onClose}>×</button></div><div className="modal-form single"><label>工单标题<span>*</span><input autoFocus value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="简要描述问题"/></label><label>业务组<span>*</span><select value={form.roleId} onChange={e=>setForm({...form,roleId:e.target.value})}><option value="">请选择负责业务组</option>{roles.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><label>审批人<input className="readonly-field" value={approverName||'正在获取直接领导'} readOnly /></label><label>优先级<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option value="LOW">低</option><option value="NORMAL">普通</option><option value="HIGH">高</option><option value="URGENT">紧急</option></select></label><label>问题描述<span>*</span><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="请描述问题、影响范围和期望结果"/></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>取消</button><button className="primary" disabled={saving} onClick={submit}>{saving?'提交中…':'提交工单'}</button></div></div></div></div>}
function flowPeople(ticket,events){const names=[ticket.submitter_name||'—','提交人的上级',ticket.leader_name||'执行人的上级',ticket.leader_name||'待指派',ticket.assignee_name||'待指派',ticket.verifier_name||ticket.submitter_name||'—',ticket.verifier_name||ticket.submitter_name||'—'];const node={CREATE:0,submitter_approve:1,approve:2,assign:3,reassign:4,complete:4,verify_ok:5,verify_fail:4,close:6};(events||[]).forEach(ev=>{const i=node[ev.action];if(i!=null&&ev.actor_name)names[i]=ev.actor_name;});return names;}
function TicketFlow({ticket,events:initialEvents,compact=true}){const [events,setEvents]=useState(initialEvents||[]);const [steps,setSteps]=useState([]);useEffect(()=>{api('/workflow').then(setSteps).catch(()=>{})},[]);useEffect(()=>{if(initialEvents){setEvents(initialEvents);return;}api('/tickets/'+ticket.id+'/events').then(setEvents).catch(()=>{})},[ticket.id,initialEvents]);const visible=steps.filter(step=>Number(step.enabled)===1);const index=Math.max(0,visible.findIndex(step=>step.status===ticket.status));const names=flowPeople(ticket,events);const actorText={submitter:'提交人',submitter_leader:'提交人的上级',executor_leader:'执行人的上级',group_leader:'业务组 Leader',assignee:'执行人'};return <div className={compact?'ticket-progress':'flow-track'}>{visible.map((step,i)=><React.Fragment key={step.code}><div className={'flow-node '+(ticket.status==='REJECTED'?'todo':i<index?'done':i===index?'current':'todo')} title={step.name+'：'+(actorText[step.actor]||'')}><span>{i+1}</span>{compact?<b>{step.name}</b>:<><b>{step.name}{step.status==='IN_PROGRESS'&&ticket.status==='REWORK_REQUIRED'?'（返工）':''}</b><small>{actorText[step.actor]}</small></>}</div>{i<visible.length-1&&<i className={'flow-line '+(ticket.status==='REJECTED'?'':i<index?'done':'')}/>}</React.Fragment>)}</div>;}
