function Root(){const hash=new URLSearchParams(String(location.hash||'').replace(/^#/,''));if(hash.get('token')){localStorage.setItem('flowdesk_token',hash.get('token'));history.replaceState(null,'',location.pathname+location.search);}const initialError=hash.get('error')||'';if(hash.get('token')||hash.get('error'))history.replaceState(null,'',location.pathname+location.search);const[u,setU]=useState(null),[ready,setReady]=useState(false),[loginError,setLoginError]=useState(initialError);useEffect(()=>{const token=localStorage.getItem('flowdesk_token');if(!token){setReady(true);return;}api('/auth/me').then(setU).catch(()=>{localStorage.removeItem('flowdesk_token')}).finally(()=>setReady(true));},[]);if(!ready)return null;return u?<App user={u} logout={()=>{localStorage.removeItem('flowdesk_token');setU(null)}}/>:<Login onLogin={setU} initialError={loginError}/>;}createRoot(document.getElementById('root')).render(<Root/>);
